INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "Académie Michèle Provost", "grades": "K-11", "main language of instruction": "French", "public/private": "private", "class size": "K: 20; G1-G6: 25", "accessibility (wait list, lottery, etc)": "100 students per grade, first-come-first-served", "outdoor/sports time": "1 hour daily, weekly gym class, plus weekly \"sports afternoon\"", "outdoor/playground space": "separate paved yard for high school & elementary school students. Twice weekly access to play structure. Older elementary + high school students visit Mount Royal, nearby park.", "extracurriculars": "ballet, judo, chess, piano, violin, yoga, etc. for extra $", "lunch service": "$520 for supervision only; $1300 for hot lunch, served to students (not cafeteria-style)", "second language": "English K-6", "quality & retention rate of teaching staff": "I only know that my kid''s K teacher has been there for 7 years", "enriched STEM (science, technology, engineering, math)": "enriched math", "before/after school care": "free before-school care as of 7:30 am and after-school until 4:30 p.m. $990 for after-school care past 4:30 pm. K: free time G1-G6: homework support", "pedagogy": "traditional", "transportation": "no bus; car-pooling available but limited", "gifted program": "no, just enriched math and advanced french (langue d''enseignment)", "third language": "Spanish as extra curricular for extra $", "enriched Arts program": "No", "use of electronic devices": "iPads as of K", "homework": "none in K", "bullying policy": "yes, plus email to report incidences", "caring/supportive/nurturing ": "onsite nurse, excellent supervisors during recess and lunch break", "diversity": "cultural and racial diversity; no economic diversity", "parental involvement": "parents can volunteer as field trip chaperones, but parental involvement is generally limited", "learning disabilities": "Orthopedagog, orthophonist, psycho-educatrice, private lessons by the teachers of school on site for extra $.", "cost": "$3880-$5180 depending on lunch & daycare options", "Open House 2017": "every Thursday, by appointment"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "Charles LeMoyne, volet alternatif", "grades": "K-6", "main language of instruction": "French", "public/private": "public", "class size": "Average of 15 per class. Multiage in Grade 4,5 and 6, where there are smaller groups", "accessibility (wait list, lottery, etc)": "Priority is given to PSC, Sud-Ouest, CSDM in that order. ", "outdoor/sports time": "Outings everyday to observe insects, plants. Swimming bi-weekly, Ice skating. Longer lunch break for K", "outdoor/playground space": "Paved yard outside of the school, in a public area for all kindergarden and primary students", "extracurriculars": "Music (orchestra), Skiing", "lunch service": "Service provided by \"Le Garde Manger\" The cost is according to the family revenue", "second language": "English1-6", "quality & retention rate of teaching staff": "New administration 2 years ago", "enriched STEM (science, technology, engineering, math)": "tbc", "before/after school care": "to paid, before school (3$), lunch (2$), and after school (5$). Aprox $8.15 for 3 periods// $9 for pedagogical. Optional activities during ped days as well ", "pedagogy": "Freinet. Parents Coeducateur", "transportation": "Bus for Language program", "gifted program": "TBC", "third language": "There is a program organized the CSDM to teach children the language of their parents (spanish, chinese, arabic, hindi, etc). I sent an email to inquiry", "enriched Arts program": "TBC", "use of electronic devices": "Yes", "homework": "none in K; homework depends on if self-selected work is completed in class, plus some lessons sent home; lots of projects", "bullying policy": "TBC", "caring/supportive/nurturing ": "onsite nurse", "diversity": "cultural, racial and economical diversity", "parental involvement": "1 h per week per family", "learning disabilities": "yes", "cost": "N/A", "Open House 2017": "2017-10-03 00:00:00"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "Charles LeMoyne, programme régulier", "grades": "preK-6", "main language of instruction": "French", "public/private": "public", "accessibility (wait list, lottery, etc)": "guaranteed entry to those in school''s zone", "learning disabilities": "YES"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "École de la Petite Bourgogne", "grades": "preK-6", "main language of instruction": "French", "public/private": "public", "class size": "max 20", "accessibility (wait list, lottery, etc)": "guaranteed entry to those in school''s zone", "outdoor/sports time": "K: after lunch (45 min) G1-G6: 30 min recess + lunch", "outdoor/playground space": "Paved yard and access to public park (built in 2013)", "extracurriculars": "Science program in grade 5 with ETS, CoOpera with Opera de MTL in Grade 6, Scientifines (science program for girls), many free activities outside of the school during the year", "lunch service": "$720 for supervision + $720 for meal", "second language": "English as of Grade 1", "before/after school care": "before/after school care = $8.15/day maximum", "pedagogy": "traditional", "transportation": "Bus if you live more than 1.3km from the school", "use of electronic devices": "Interactive whiteboard in each class", "homework": "none in K; G1-G6: yes, and you can ask for more", "bullying policy": "Tolerance 0", "caring/supportive/nurturing ": "Nurse one day per week, also a dental hygienist with free consultation", "diversity": "cultural diversity, no social diversity (mostly low income families)", "parental involvement": "Not much, starting to change with creation of PPO this year", "learning disabilities": "Many specialists available in the school", "cost": "In K = between $47.00 and $2235 depending on lunch and daycare options", "Open House 2017": "2018-01-01 00:00:00"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "École internationale", "grades": "K-11", "main language of instruction": "French", "public/private": "public", "accessibility (wait list, lottery, etc)": "French test for entry", "third language": "Spanish", "Open House 2017": "2017-10-07 00:00:00"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "F.A.C.E. (CSDM)", "grades": "K-11", "main language of instruction": "French", "public/private": "public", "class size": 20, "accessibility (wait list, lottery, etc)": "lottery system", "outdoor/sports time": "recess + once a week gym", "outdoor/playground space": "paved yard, small back courtyard, access to McGill campus", "extracurriculars": "Chess, cooking, jewelry", "lunch service": "yes 4$ each meal", "before/after school care": "servide de garde$", "pedagogy": "vocation particulière", "transportation": "no bus", "third language": "no", "enriched Arts program": "yes", "use of electronic devices": "no", "homework": "None in k", "bullying policy": "Tolerance 0 (Edited by FACE parent: Bullying is taken to be normal at this school, both by parents and school admin. The School does \"interventions\" but \"rough play\" during recess is allowed.) (Another FACE parent - no problems with bullying in 6 years.  One troublesome incident in SDG dealt with immediately)", "caring/supportive/nurturing ": "nurse", "diversity": "very diverse", "parental involvement": "some required", "learning disabilities": "specialists", "cost": "$500 a year", "Open House 2017": "2017-09-26 00:00:00"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "F.A.C.E. (EMSB)*", "grades": "K-11", "main language of instruction": "English", "public/private": "public", "class size": "idk - approx 20 or so", "accessibility (wait list, lottery, etc)": "space still available for 2017-2018", "outdoor/sports time": "recess + once a week gym", "outdoor/playground space": "paved yard, small back courtyard, access to McGill campus", "extracurriculars": "Chess, Geordie Theatre, FACE Up! (varies), University camps", "lunch service": "yes 4$ each meal if you buy a card (no auto refills like CSDM)", "second language": "50/50 English/French", "quality & retention rate of teaching staff": "great new administration - only a couple of less than great teachers", "enriched STEM (science, technology, engineering, math)": "not sure - there are advanced math and science courses in high school", "before/after school care": "there is a service de garde $", "transportation": "no bus", "gifted program": "there is advanced french and math offered to individual students, who are pulled from class", "third language": "no", "enriched Arts program": "yes", "use of electronic devices": "no", "homework": "Yes, starting in G1", "bullying policy": "Tolerance 0 (Edited by FACE parent: Bullying is taken to be normal at this school, both by parents and school admin. The School does \"interventions\" but \"rough play\" during recess is allowed.) (Another FACE parent - no problems with bullying in 6 years.  One troublesome incident in SDG dealt with immediately)", "caring/supportive/nurturing ": "nurse, sometimes volunteer parents", "diversity": "very diverse", "parental involvement": "some required", "learning disabilities": "students with learning disabilities are encouraged to go elsewhere - this is an enriched curriculum (arts and music) and very demanding.", "cost": "$500 a year", "Open House 2017": "2017-09-26 00:00:00"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "Marie de France", "grades": "K-11", "main language of instruction": "French", "public/private": "private", "class size": "Mad 25", "accessibility (wait list, lottery, etc)": "Selective.", "outdoor/sports time": "Different programs , pool once a week , soccer ", "outdoor/playground space": "Private Playground for the smallest ", "extracurriculars": "Chess , soccer , theater, science ,music", "before/after school care": "Before school 7:30am after school 6:00pm ", "pedagogy": "French program ", "transportation": "Bus  but not for verdun areas ", "third language": "Spanish , mandarin ", "enriched Arts program": "Yes", "use of electronic devices": "Yes", "homework": "Yes in Maternelle ", "bullying policy": "Tolerance 0", "caring/supportive/nurturing ": "Nurse", "diversity": "Very diverse", "parental involvement": "Yes ", "cost": "$4000 a year not included lunch service , daycare, extracurricular ", "Open House 2017": "October"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "Nouvelle Vague", "grades": "K-6 (with the intention of adding grades as the school grows)", "main language of instruction": "Bilingual", "public/private": "private", "class size": "There are 15 students in the entire school this year...", "use of electronic devices": "Yes", "cost": 11000, "Open House 2017": "September 28th"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "Roslyn*", "grades": "K-6", "main language of instruction": "French immersion (English school board)", "public/private": "public", "class size": "depends on the grade, K: 18 1-2:20 and afterwards I''m not sure", "accessibility (wait list, lottery, etc)": "guaranteed entry to those in school''s zone", "outdoor/sports time": "Different per grade gym in K:30 min 4xwk, but I think they try and let the older grades twice a week", "outdoor/playground space": "One playground but they separate the grades when they go out so that big kids don''t hurt the younger ones", "extracurriculars": "A vast choice, organized by the parent volunteer community at the school", "lunch service": "$325 in total. The parent volunteer community organizes 15 pizza lunches that are $75 for the year. They have another service for hot meals that you can pay as you want.", "second language": "First 3 years are completely in French then the curriculum is taught 50/50", "quality & retention rate of teaching staff": "very good ", "before/after school care": "before school is with the Westmount YMCA, $3 something per hour. For afer school there are various options, the ones I know are the Westmount YMCA about $8 an hour, the Greene Center and the Tyndale Community Center ($180 a year but they''re not open on Ped days)", "transportation": "Bussing within the 1.3 km of the school", "third language": "Italian as an extracurricular activity", "enriched Arts program": "Try to emphasize Science, Math and Music", "use of electronic devices": "Interactive whiteboard in the classroom", "homework": "none in K. reasonable amounts in older grades. ", "bullying policy": "zero tolerance", "caring/supportive/nurturing ": "Nurse from the CLSC once a week, but parents volunteer so that the nursing room is available every day", "diversity": "pretty diverse", "parental involvement": "Very big, volunteer community called HandS Home and School", "cost": "80$ for school supplies, 10$ per gym shirt, $325 lunch", "Open House 2017": "October"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "St-Zotique", "grades": "preK-6", "main language of instruction": "French", "public/private": "public", "accessibility (wait list, lottery, etc)": "guaranteed entry to those in school''s zone"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "Stanislas", "grades": "K-CEGEP", "main language of instruction": "French", "public/private": "private", "class size": "varies. 30 in K, less in higher grades", "accessibility (wait list, lottery, etc)": "Selective. Entrance exam required for elementary and up.", "outdoor/sports time": "Vraiment beaucoup... mais ça dépend des niveaux.", "outdoor/playground space": "Cours, gym, salle de motricité.", "extracurriculars": "Music, circus, chess, piano, art, contes et créations, etc. for extra $", "lunch service": "Yes, for a fee; no fee for lunch supervision", "second language": "English", "before/after school care": "Yes, included before school; for a fee after school", "pedagogy": "French (from France) program", "bullying policy": "There is an anti-bullying plan posted on their website", "cost": "$4,500 not including daycare or lunch options", "Open House 2017": "2017-09-30 00:00:00"}');
INSERT INTO school_legacy_records (record) VALUES ('{"Schools/Topics": "Académie Ste-Anne", "grades": "K-6 with a sister high school & CEGEP", "main language of instruction": "Bilingual", "public/private": "private", "second language": "school is bilingual", "enriched STEM (science, technology, engineering, math)": "Yes", "transportation": "bus to Westmount", "learning disabilities": "If required, students have access to specialized assistance and support services", "Open House 2017": "2017-09-23 00:00:00"}');
